input.sparql:
SELECT ?zone ?zone_name ?temp_point ?temp_id ?cp_point ?cp_id WHERE {
  ?zone a brick:Zone .
  OPTIONAL {
    ?zone brick:hasTemperaturePoint ?temp_point .
    ?temp_point ref:hasTimeseriesId ?temp_id .
  }
  OPTIONAL {
    ?zone brick:hasCoolingSetpointPoint ?cp_point .
    ?cp_point ref:hasTimeseriesId ?cp_id .
  }
  ?zone rdfs:label ?zone_name .
}

SELECT ?zone ?zlabel ?point ?pointClass ?id ?pname WHERE {
  ?zone a brick:HVAC_Zone .
  ?point brick:isPointOf ?zone .
  ?point a ?pointClass .
  OPTIONAL { ?point ref:hasTimeseriesId ?id }
  OPTIONAL { ?point rdfs:label ?pname }
}

SELECT ?point ?id ?name ?label WHERE {
  ?point ref:hasTimeseriesId ?id .
  OPTIONAL { ?point ref:ifcName ?name }
  OPTIONAL { ?point rdfs:label ?label }
  FILTER(?point != "x")
} LIMIT 60
